INSERT INTO questions (diaries_id, question_id, question_text, choice_a, choice_b, choice_c) VALUES
    (1, 1, 'この記述では「年明けは机の片付けから始めた」とあります。このとき頭の中を整えるために最初にしたこととして近いのはどれですか？', '項目や順番を書き出して整理した', '全体の意味や流れを先に見ようとした', 'とりあえず動きながら感覚を確かめた'),
    (1, 2, 'この記述では「1月にやることを三つだけ紙に書いたら、部屋も気持ちも少し軽くなった」とあります。特に意識して整えていたものはどれに近いですか？', '手元の情報や手順の並び', 'この出来事が先でどうつながるか', 'やりやすさや手触り'),
    (1, 3, 'このときは「1月にやることを三つだけ紙に書いたら、部屋も気持ちも少し軽くなった」とあります。整理や準備を進めるうえで一番優先したのはどれですか？', '基準や順番が明確なこと', '無理なく続けられて気持ちが荒れないこと', 'あとで動かせる余白を残すこと'),
    (2, 1, 'この場面では「朝は家族で初詣に行き、午後は返せていなかった連絡をまとめて返した」とあります。やり取りの中で自分の考えが固まった流れとして一番近いのはどれですか？', 'まず相手とやり取りする中で考えが固まった', '相手の反応を受けてから一人で整理して固まった', '会話とは別にその場の空気で自然に決まっていった'),
    (2, 2, 'この場面では「ゆっくり進む一日が思った以上にありがたかった」とあります。やり取りの最中に一番強く拾っていたものはどれに近いですか？', '相手の言葉や事実関係のずれ', 'そのやり取りが持つ意味や関係の変化', 'その場の空気や温度感'),
    (2, 3, 'このときは「ゆっくり進む一日が思った以上にありがたかった」とあります。最終的に行動を決める決め手として近いのはどれですか？', '筋が通っていて説明しやすいこと', '自分や相手に無理がなく続けやすいこと', '今は決め切らず後で調整できること'),
    (3, 1, 'この記述では「今日はとても静かな一日だった」とあります。このとき自分の気持ちや考えをつかむ流れとして近いのはどれですか？', 'まず一人で言葉にして輪郭をつかんだ', '意味やつながりを考えるうちに見えてきた', 'その場の感覚に任せて流れを見た'),
    (3, 2, 'この記述では「小説を少し読み、夕飯の支度を手伝い、にぎやかな予定がないことをむしろ心地よく感じた」とあります。このとき一番見ていたものとして近いのはどれですか？', 'その場で起きている具体的な事実', '出来事の意味や先の広がり', '空気感や感触の変化'),
    (3, 3, 'このときは「小説を少し読み、夕飯の支度を手伝い、にぎやかな予定がないことをむしろ心地よく感じた」とあります。最終的な判断を支えたものとして近いのはどれですか？', '基準がはっきりしていて段取りを決めやすいこと', '自分や相手が無理なく続けられること', '余白を残して後から調整できること'),
    (4, 1, 'この記述では「仕事が始まったので、12月のメモを見返して本当に残すべきタスクだけを書き出した」とあります。このとき頭の中を整えるために最初にしたこととして近いのはどれですか？', '項目や順番を書き出して整理した', '全体の意味や流れを先に見ようとした', 'とりあえず動きながら感覚を確かめた'),
    (4, 2, 'この記述では「順番が見えただけで今週の重さが少し減った」とあります。特に意識して整えていたものはどれに近いですか？', '手元の情報や手順の並び', 'この出来事が先でどうつながるか', 'やりやすさや手触り'),
    (4, 3, 'このときは「順番が見えただけで今週の重さが少し減った」とあります。整理や準備を進めるうえで一番優先したのはどれですか？', '基準や順番が明確なこと', '無理なく続けられて気持ちが荒れないこと', 'あとで動かせる余白を残すこと'),
    (5, 1, 'この場面では「午前中の長い会議で、誰が何を持つのかがようやくはっきりした」とあります。やり取りの中で自分の考えが固まった流れとして一番近いのはどれですか？', 'まず相手とやり取りする中で考えが固まった', '相手の反応を受けてから一人で整理して固まった', '会話とは別にその場の空気で自然に決まっていった'),
    (5, 2, 'この場面では「終わってみれば、朝よりずっと整理された気分で席を立てた」とあります。やり取りの最中に一番強く拾っていたものはどれに近いですか？', '相手の言葉や事実関係のずれ', 'そのやり取りが持つ意味や関係の変化', 'その場の空気や温度感'),
    (5, 3, 'このときは「終わってみれば、朝よりずっと整理された気分で席を立てた」とあります。最終的に行動を決める決め手として近いのはどれですか？', '筋が通っていて説明しやすいこと', '自分や相手に無理がなく続けやすいこと', '今は決め切らず後で調整できること'),
    (6, 1, 'この記述では「数日気になっていた小さなバグを直した」とあります。このとき自分の気持ちや考えをつかむ流れとして近いのはどれですか？', 'まず一人で言葉にして輪郭をつかんだ', '意味やつながりを考えるうちに見えてきた', 'その場の感覚に任せて流れを見た'),
    (6, 2, 'この記述では「大きな成果ではないけれど、あの引っかかりが消えただけで気分まで軽くなった」とあります。このとき一番見ていたものとして近いのはどれですか？', 'その場で起きている具体的な事実', '出来事の意味や先の広がり', '空気感や感触の変化'),
    (6, 3, 'このときは「大きな成果ではないけれど、あの引っかかりが消えただけで気分まで軽くなった」とあります。最終的な判断を支えたものとして近いのはどれですか？', '基準がはっきりしていて段取りを決めやすいこと', '自分や相手が無理なく続けられること', '余白を残して後から調整できること'),
